command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/outbound-storage-drag-20261006"
$main="4f03ea8bc499cd8e4d064431753d4f7aefac0fff"
$product="0d23048d47b158b98c2aff0cf7f3ec5ffc8c5ebb"
$regression="36b46b96973ef4777f96dffc64413e3c9d548ca5"
$candidate="eae58315ee638c2917a3f10a822ce612631efc7e"
$temp=Join-Path $env:RUNNER_TEMP ("outbound-drag-final-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --no-tags --prune
  if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
  $mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
  $branchSha=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($mainSha -ne $main){throw "main moved before outbound drag final validation: $mainSha"}
  if($branchSha -ne $candidate){throw "candidate moved before outbound drag final validation: $branchSha"}

  & git diff --quiet $product $candidate -- app src
  if($LASTEXITCODE -ne 0){throw "accepted outbound drag product code changed after #464"}
  & git diff --quiet $regression $candidate -- tests/winui
  if($LASTEXITCODE -ne 0){throw "accepted outbound/same-app GUI contracts changed after #466"}

  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & git diff --check $main $candidate
  if($LASTEXITCODE -ne 0){throw "git diff --check failed"}

  & python -X utf8 -m unittest tests.winui.test_outbound_drag_contract tests.winui.test_transfer_budget_contract
  if($LASTEXITCODE -ne 0){throw "outbound drag source contracts failed"}

  & python -X utf8 tools\winui\run_checks.py fast --before $regression --head $candidate
  if($LASTEXITCODE -ne 0){throw "final P2 FAST validation failed"}

  & cmd /c test.bat policy
  if($LASTEXITCODE -ne 0){throw "P2 policy validation failed"}

  Write-Host ("OUTBOUND_DRAG_ACCEPTED_PRODUCT="+$product)
  Write-Host ("OUTBOUND_DRAG_ACCEPTED_REGRESSION="+$regression)
  Write-Host ("OUTBOUND_DRAG_FINAL_CANDIDATE="+$candidate)
  Write-Host "OUTBOUND_DRAG_FINAL_VALIDATION=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
